  Map<String,dynamic> toCloudJson(String clientId){final shop=AppointmentStore.shopId;if(shop==null)throw StateError('Usuário sem estabelecimento selecionado.');final p=time.split(':');final local=DateTime(DateTime.parse(dateIso).year,DateTime.parse(dateIso).month,DateTime.parse(dateIso).day,int.parse(p[0]),int.parse(p[1]));return {'id':id,'barbershop_id':shop,'client_id':clientId,'service_id':serviceId,'barber_id':barberId,'service':service,'duration':duration,'duration_minutes':durationMinutes,'price':price,'barber':barber,'date_iso':dateIso,'time':time,'starts_at':local.toUtc().toIso8601String(),'created_at_iso':createdAtIso,'status':'scheduled'};}
