 AppointmentStore._(); static const _key='appointments_v1',_clientShopKey='client_shop_id_v2'; static const _supabaseUrl=String.fromEnvironment('SUPABASE_URL',defaultValue:'https://drvaacngbtnjxdeakgnn.supabase.co'),_supabasePublishableKey=String.fromEnvironment('SUPABASE_PUBLISHABLE_KEY',defaultValue:'sb_publishable_FAPJ5-5m7nnvXP18vw85yQ_QuVAjum8'); static bool _cloudReady=false; static String? _cloudError,_shopId,_shopName,_memberRole;
