 static Future<void> initializeCloud()async{_cloudReady=false;_cloudError=null;_shopId=null;_shopName=null;_memberRole=null;if(_supabaseUrl.isEmpty||_supabasePublishableKey.isEmpty){_cloudError='Configuração do Supabase ausente no APK.';return;}try{await Supabase.initialize(url:_supabaseUrl,publishableKey:_supabasePublishableKey);if(client.auth.currentUser?.isAnonymous==true)await client.auth.signOut();if(client.auth.currentUser!=null)await refreshMembership();else _cloudError='Entre com sua conta.';}catch(e,s){_cloudReady=false;_cloudError=e.toString();debugPrint('[Supabase] Falha ao inicializar: $e');debugPrintStack(stackTrace:s);}}
 static Future<void> signIn(String email,String password)async{_cloudReady=false;_cloudError=null;await client.auth.signInWithPassword(email:email.trim(),password:password);await refreshMembership();}
