 static Future<List<Map<String,dynamic>>> listActiveBarbershops()async{if(!signedIn)throw StateError('Faça login primeiro.');final rows=await client.from('barbershops').select('id,name,slug').eq('active',true).order('name');return(rows as List<dynamic>).cast<Map<String,dynamic>>();}
 static Future<void> selectClientShop(String id)async{final user=currentUser;if(user==null||user.isAnonymous==true)throw StateError('Faça login primeiro.');final rows=await client.from('barbershops').select('id,name').eq('id',id).eq('active',true).limit(1);final list=rows as List<dynamic>;if(list.isEmpty)throw StateError('Estabelecimento indisponível.');final shop=list.first as Map<String,dynamic>;final prefs=await SharedPreferences.getInstance();await prefs.setString(_clientShopKeyFor(user),id);_shopId=id;_shopName=shop['name']?.toString();_memberRole=null;_cloudReady=true;_cloudError=null;}
 static Future<void> clearClientShop()async{final user=currentUser;if(user!=null){final prefs=await SharedPreferences.getInstance();await prefs.remove(_clientShopKeyFor(user));}_shopId=null;_shopName=null;_cloudReady=false;_cloudError='Escolha um estabelecimento para continuar.';}
 static Future<void> claimOwnerAccess(String inviteCode)async{if(!signedIn)throw StateError('Faça login primeiro.');await client.rpc('claim_barbershop_owner',params:{'invite_code':inviteCode.trim()});await refreshMembership();}
 static Future<List<Appointment>> load()async{if(cloudEnabled){try{final r=await _loadRemote();await _save(r);return r;}catch(e,s){_cloudError=e.toString();debugPrint('[Supabase] Falha ao carregar agenda: $e');debugPrintStack(stackTrace:s);}}return _loadLocal();}
 static Future<void> add(Appointment a)async{if(!cloudEnabled)throw StateError(_cloudError??'Agenda na nuvem indisponível.');try{await _addRemote(a);_cloudError=null;}catch(e,s){_cloudError=e.toString();debugPrint('[Supabase] Falha ao inserir agendamento: $e');debugPrintStack(stackTrace:s);rethrow;}final items=await _loadLocal();items.removeWhere((x)=>x.id==a.id);items.add(a);items.sort(_compareAppointments);await _save(items);}
 static Future<void> remove(String id)async{if(!cloudEnabled)throw StateError(_cloudError??'Agenda na nuvem indisponível.');final cancelledBy=isAdmin?'admin':'client',cancelledAtIso=DateTime.now().toUtc().toIso8601String();try{await _removeRemote(id,cancelledBy,cancelledAtIso);_cloudError=null;}catch(e,s){_cloudError=e.toString();debugPrint('[Supabase] Falha ao cancelar agendamento: $e');debugPrintStack(stackTrace:s);rethrow;}final items=await _loadLocal();final index=items.indexWhere((x)=>x.id==id);if(index>=0){items[index]=items[index].copyWith(status:'cancelled',cancelledBy:cancelledBy,cancelledAtIso:cancelledAtIso);await _save(items);}}
 static Future<void> complete(String id)async{if(!cloudEnabled)throw StateError(_cloudError??'Agenda na nuvem indisponível.');if(!isAdmin)throw StateError('Apenas o estabelecimento pode concluir atendimentos.');try{final row=await client.rpc('complete_appointment',params:{'p_appointment_id':id});_cloudError=null;final items=await _loadLocal();final index=items.indexWhere((x)=>x.id==id);if(index>=0){final m=row is Map<String,dynamic>?row:(row is List&&row.isNotEmpty?Map<String,dynamic>.from(row.first as Map):<String,dynamic>{});items[index]=items[index].copyWith(status:'completed',completedAtIso:m['completed_at']?.toString()??DateTime.now().toUtc().toIso8601String(),completionSource:m['completion_source']?.toString()??'manual');await _save(items);}}catch(e,s){_cloudError=e.toString();debugPrint('[Supabase] Falha ao concluir agendamento: $e');debugPrintStack(stackTrace:s);rethrow;}}
 static Future<List<Appointment>> _loadLocal()async{final p=await SharedPreferences.getInstance();final raw=p.getString(_key);if(raw==null||raw.isEmpty)return[];try{final d=jsonDecode(raw) as List<dynamic>;final items=d.map((x)=>Appointment.fromJson(x as Map<String,dynamic>)).toList();items.sort(_compareAppointments);return items;}catch(_){return[];}}
 static Future<List<Appointment>> _loadRemote()async{final user=client.auth.currentUser,shop=shopId;if(user==null)throw StateError('Sessão Supabase não autenticada.');if(shop==null)throw StateError('Estabelecimento não selecionado.');if(isAdmin){final rows=await client.rpc('admin_appointments_with_client_identity');final items=(rows as List<dynamic>).map((x)=>Appointment.fromCloudJson(x as Map<String,dynamic>)).toList();items.sort(_compareAppointments);return items;}var q=client.from('appointments').select('id,service,duration,price,barber,date_iso,time,created_at_iso,status,cancelled_by,cancelled_at,completed_at,completion_source,client_phone').eq('barbershop_id',shop).eq('client_id',user.id);final rows=await q.order('date_iso').order('time');final items=(rows as List<dynamic>).map((x)=>Appointment.fromCloudJson(x as Map<String,dynamic>)).toList();items.sort(_compareAppointments);return items;}
 static Future<void> _addRemote(Appointment a)async{final user=client.auth.currentUser;if(user==null)throw StateError('Sessão Supabase não autenticada.');try{await client.from('appointments').insert(a.toCloudJson(user.id));}on PostgrestException catch(e){if(e.code=='23505')throw const AppointmentConflictException();rethrow;}}
 static Future<void> _removeRemote(String id,String cancelledBy,String cancelledAtIso)async{final shop=shopId,user=client.auth.currentUser;if(user==null)throw StateError('Sessão Supabase não autenticada.');if(shop==null)throw StateError('Estabelecimento não selecionado.');var q=client.from('appointments').update({'status':'cancelled','cancelled_by':cancelledBy,'cancelled_at':cancelledAtIso}).eq('id',id).eq('barbershop_id',shop);if(!isAdmin)q=q.eq('client_id',user.id);await q;}
 static Future<void> _save(List<Appointment> items)async{final p=await SharedPreferences.getInstance();await p.setString(_key,jsonEncode(items.map((x)=>x.toJson()).toList()));}
 static int _compareAppointments(Appointment a,Appointment b){DateTime v(Appointment x){final p=x.time.split(':');return DateTime(x.date.year,x.date.month,x.date.day,int.parse(p[0]),int.parse(p[1]));}return v(a).compareTo(v(b));}
